package io.aegiswire.policy;
import io.aegiswire.core.*; import java.util.*;
public class Rule { private final String id,note; private final Severity severity; private final int score; private final List<String> tags; private final List<Condition> conditions; public Rule(String id,Severity sev,int score,String note,List<String>tags,List<Condition>cs){this.id=id;severity=sev;this.score=score;this.note=note;this.tags=tags;conditions=cs;} public boolean matches(ScanContext c){ for(Condition x:conditions) if(!x.matches(c)) return false; return true; } public Finding finding(){ Map<String,String> e=new LinkedHashMap<String,String>(); e.put("score",Integer.toString(score)); e.put("tags",String.join(",",tags)); return new Finding(id,severity,note,e); } public int score(){return score;} }
